      starter: 'def clean_title(text):\n    return text\n\nprint(clean_title("  the   lord of   THE rings "))\n',
      solution: 'def clean_title(text):\n    return " ".join(text.split()).title()\n\nprint(clean_title("  the   lord of   THE rings "))   # The Lord Of The Rings\n',
