      starter: 'data = [4, -2, 7, 0, -9, 3, 7, 4]\n\n# (a) unique values, order kept\nprint()\n# (b) sum of the positive numbers\nprint()\n# (c) sorted by absolute value\nprint()\n# (d) index of the first negative number\nprint()\n',
      solution: 'data = [4, -2, 7, 0, -9, 3, 7, 4]\n\nunique = []\nfor x in data:\n    if x not in unique:\n        unique.append(x)\nprint(unique)                               # [4, -2, 7, 0, -9, 3]\nprint(sum(x for x in data if x > 0))        # 25\nprint(sorted(data, key=abs))                # [0, -2, 3, 4, 4, 7, 7, -9]\nprint(next(i for i, x in enumerate(data) if x < 0))   # 1\n',
